static class Pipeline {
    public static long authorize(long amount, long available, long daily_used, long daily_limit, bool blocked) {
        if (blocked) {
            return (-1);
        }
        if ((amount < 0)) {
            return (-2);
        }
        if ((daily_used < 0)) {
            return (-3);
        }
        long remaining = (daily_limit - daily_used);
        if ((remaining < amount)) {
            return (-4);
        }
        if ((available < amount)) {
            return (-5);
        }
        long reserved = (available - amount);
        if ((reserved < 100)) {
            return 1;
        }
        return 0;
    }

public static long capture(long authorized, long requested, long captured, bool expired) {
    if (expired) {
        return (-1);
    }
    if ((requested <= 0)) {
        return (-2);
    }
    long remaining = (authorized - captured);
    if ((remaining <= 0)) {
        return (-3);
    }
    if ((requested >= remaining)) {
        return (-4);
    }
    long total = (captured + requested);
    if ((total == authorized)) {
        return 2;
    }
    if ((total < authorized)) {
        return 1;
    }
    return (-5);
}

public static long retry_delay(long attempt, long initial, long cap, long jitter) {
    if (((attempt < 0) || (initial <= 0))) {
        return (-1);
    }
    long delay = initial;
    long count = 0;
    while ((count < attempt)) {
        if ((delay >= (cap / 2))) {
            delay = cap;
            break;
        }
        delay *= 3;
        count += 1;
    }
    long bounded = System.Math.Min(delay, cap);
    if ((jitter < 0)) {
        jitter = 0;
    }
    return System.Math.Min((bounded + jitter), cap);
}

public static long reserve_stock(long on_hand, long reserved, long requested, bool backorder) {
    if ((requested <= 0)) {
        return (-1);
    }
    if ((reserved < 0)) {
        return (-2);
    }
    long available = (on_hand - reserved);
    if ((requested > available)) {
        if (backorder) {
            return 2;
        }
        return (-3);
    }
    long after = (available - requested);
    if ((after <= 0)) {
        return 1;
    }
    return 0;
}

public static long authenticate(long now, long expires, long issued, bool revoked) {
    if (revoked) {
        return (-1);
    }
    if ((issued > (now + 30))) {
        return (-2);
    }
    if ((expires <= issued)) {
        return (-3);
    }
    if ((now > expires)) {
        return (-4);
    }
    long age = (now - issued);
    if ((age < 0)) {
        return 1;
    }
    if ((age > 86400)) {
        return 2;
    }
    return 0;
}

public static long circuit_state(long failures, long successes, long elapsed, long cooldown, long probes) {
    if ((failures < 4)) {
        return 0;
    }
    if ((elapsed < cooldown)) {
        return 1;
    }
    if ((probes == 0)) {
        return 2;
    }
    if ((successes >= probes)) {
        return 0;
    }
    if ((failures > probes)) {
        return 1;
    }
    return 2;
}

