blocks.source:
func authorize(amount int64, available int64, daily_used int64, daily_limit int64, blocked bool) int64 {
    if blocked {
        return (-1)
    }
    if (amount < 0) {
        return (-2)
    }
    if (daily_used < 0) {
        return (-3)
    }
    var remaining int64 = (daily_limit - daily_used)
    if (remaining < amount) {
        return (-4)
    }
    if (available < amount) {
        return (-5)
    }
    var reserved int64 = (available - amount)
    if (reserved < 100) {
        return 1
    }
    return 0
}

func capture(authorized int64, requested int64, captured int64, expired bool) int64 {
    if expired {
        return (-1)
    }
    if (requested <= 0) {
        return (-2)
    }
    var remaining int64 = (authorized - captured)
    if (remaining <= 0) {
        return (-3)
    }
    if (requested >= remaining) {
        return (-4)
    }
    var total int64 = (captured + requested)
    if (total == authorized) {
        return 2
    }
    if (total < authorized) {
        return 1
    }
    return (-5)
}

func retry_delay(attempt int64, initial int64, cap int64, jitter int64) int64 {
    if ((attempt < 0) || (initial <= 0)) {
        return (-1)
    }
    var delay int64 = initial
    var count int64 = 0
    for (count < attempt) {
        if (delay >= (cap / 2)) {
            delay = cap
            break
        }
        delay *= 3
        count += 1
    }
    var bounded int64 = min64(delay, cap)
    if (jitter < 0) {
        jitter = 0
    }
    return min64((bounded + jitter), cap)
}

func reserve_stock(on_hand int64, reserved int64, requested int64, backorder bool) int64 {
    if (requested <= 0) {
        return (-1)
    }
    if (reserved < 0) {
        return (-2)
    }
    var available int64 = (on_hand - reserved)
    if (requested > available) {
        if backorder {
            return 2
        }
        return (-3)
    }
    var after int64 = (available - requested)
    if (after <= 0) {
        return 1
    }
    return 0
}

func authenticate(now int64, expires int64, issued int64, revoked bool) int64 {
    if revoked {
        return (-1)
    }
    if (issued > (now + 30)) {
        return (-2)
    }
    if (expires <= issued) {
        return (-3)
    }
    if (now > expires) {
        return (-4)
    }
    var age int64 = (now - issued)
    if (age < 0) {
        return 1
    }
    if (age > 86400) {
        return 2
    }
    return 0
}

func circuit_state(failures int64, successes int64, elapsed int64, cooldown int64, probes int64) int64 {
    if (failures < 4) {
        return 0
    }
    if (elapsed < cooldown) {
        return 1
    }
    if (probes == 0) {
        return 2
    }
    if (successes >= probes) {
        return 0
    }
    if (failures > probes) {
        return 1
    }
    return 2
}

