blocks.source:
def authorize(amount: int, available: int, daily_used: int, daily_limit: int, blocked: bool) -> int:
    if blocked:
        return -1
    if amount < 0:
        return -2
    if daily_used < 0:
        return -3
    remaining = daily_limit - daily_used
    if remaining < amount:
        return -4
    if available < amount:
        return -5
    reserved = available - amount
    if reserved < 100:
        return 1
    return 0

def capture(authorized: int, requested: int, captured: int, expired: bool) -> int:
    if expired:
        return -1
    if requested <= 0:
        return -2
    remaining = authorized - captured
    if remaining <= 0:
        return -3
    if requested >= remaining:
        return -4
    total = captured + requested
    if total == authorized:
        return 2
    if total < authorized:
        return 1
    return -5

def retry_delay(attempt: int, initial: int, cap: int, jitter: int) -> int:
    if attempt < 0 or initial <= 0:
        return -1
    delay = initial
    count = 0
    while count < attempt:
        if delay >= cap // 2:
            delay = cap
            break
        delay *= 3
        count += 1
    bounded = min(delay, cap)
    if jitter < 0:
        jitter = 0
    return min(bounded + jitter, cap)

def reserve_stock(on_hand: int, reserved: int, requested: int, backorder: bool) -> int:
    if requested <= 0:
        return -1
    if reserved < 0:
        return -2
    available = on_hand - reserved
    if requested > available:
        if backorder:
            return 2
        return -3
    after = available - requested
    if after <= 0:
        return 1
    return 0

def authenticate(now: int, expires: int, issued: int, revoked: bool) -> int:
    if revoked:
        return -1
    if issued > now + 30:
        return -2
    if expires <= issued:
        return -3
    if now > expires:
        return -4
    age = now - issued
    if age < 0:
        return 1
    if age > 86400:
        return 2
    return 0

def circuit_state(failures: int, successes: int, elapsed: int, cooldown: int, probes: int) -> int:
    if failures < 4:
        return 0
    if elapsed < cooldown:
        return 1
    if probes == 0:
        return 2
    if successes >= probes:
        return 0
    if failures > probes:
        return 1
    return 2

